lessons.syntax:
int count = 3;
double price = 2.5;
char grade = 'A';

lessons.example:
#include <stdio.h>

int main(void) {
    int count = 3;
    double price = 2.5;
    printf("%d %.1f\n", count, price);
    return 0;
}

#include <stdio.h>

int main(void) {
    int pages = 7;
    pages = pages + 2;
    printf("%d %d\n", pages, 7 / 2);
    return 0;
}

#include <stdio.h>

int main(void) {
    double average = (8.0 + 9.0) / 2;
    printf("%.2f\n", average);
    return 0;
}

#include <stdio.h>

int main(void) {
    char grade = 'B';
    printf("%c\n", grade);
    return 0;
}

#include <stdio.h>
#include <stdbool.h>

int main(void) {
    bool ready = true;
    bool empty = false;
    printf("%d %d\n", ready, empty);
    return 0;
}

#include <stdio.h>

int main(void) {
    const int DAYS = 7;
    printf("%d\n", DAYS * 2);
    return 0;
}

#include <stdio.h>

int main(void) {
    int n = 3;
    printf("Count: %d, rate: %.1f%%\n", n, 12.5);
    return 0;
}

#include <stdio.h>

int main(void) {
    int item_count = 5;
    int Item_count = 2;
    printf("%d\n", item_count + Item_count);
    return 0;
}

#include <stdio.h>

int main(void) {
    int total = 7, count = 2;
    printf("%.1f\n", (double)total / count);
    return 0;
}

#include <stdio.h>

int main(void) {
    double a = 3.9, b = -3.9;
    printf("%d %d\n", (int)a, (int)b);
    return 0;
}

#include <stdio.h>

int main(void) {
    const double price = 8.5;
    int count = 4;
    printf("%.2f\n", price * count);
    return 0;
}
